GPU_MEM_SIZE = 80  # GB


# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """Greedily place models, then exactly repartition each worst-GPU pair."""
    eps = 1e-8
    if gpu_num <= 0:
        raise ValueError("gpu_num must be positive")
    loads = [float(m.req_rate / m.slo) for m in models]
    sizes = [float(m.model_size) for m in models]
    if any(s >= GPU_MEM_SIZE - eps for s in sizes):
        raise ValueError("A model leaves no positive KV-cache memory on a GPU")

    order = sorted(range(len(models)),
                   key=lambda i: (-loads[i], -sizes[i], i))
    bins = [[] for _ in range(gpu_num)]
    rem = [float(GPU_MEM_SIZE)] * gpu_num
    total = [0.0] * gpu_num
    for i in order:
        choices = [(total[g] / rem[g], -rem[g], g)
                   for g in range(gpu_num)
                   if rem[g] - sizes[i] > eps]
        if not choices:
            raise ValueError("Unable to find a feasible positive-residual-memory placement")
        g = min(choices)[2]
        bins[g].append(i)
        rem[g] -= sizes[i]
        total[g] += loads[i]

    def gpu_pressure(items):
        used = sum(sizes[i] for i in items)
        if GPU_MEM_SIZE - used <= eps:
            return float("inf")
        return sum(loads[i] for i in items) / (GPU_MEM_SIZE - used)

    def placement_pressure(state):
        return max(gpu_pressure(x) for x in state)

    # Repeatedly repair the currently worst GPU, inspecting each possible partner
    # once.  Each accepted repair strictly improves the complete placement.
    while True:
        worst = max(range(gpu_num), key=lambda g: gpu_pressure(bins[g]))
        before = placement_pressure(bins)
        best_state = None
        best_value = before

        for partner in range(gpu_num):
            if partner == worst:
                continue
            union = bins[worst] + bins[partner]
            k = len(union)
            if k == 0:
                continue

            candidate = None
            candidate_value = float("inf")

            def test(mask):
                nonlocal candidate, candidate_value
                left = [union[j] for j in range(k) if mask & (1 << j)]
                right = [union[j] for j in range(k) if not (mask & (1 << j))]
                if (sum(sizes[i] for i in left) >= GPU_MEM_SIZE - eps or
                        sum(sizes[i] for i in right) >= GPU_MEM_SIZE - eps):
                    return
                value = max(gpu_pressure(left), gpu_pressure(right))
                if value < candidate_value:
                    candidate_value = value
                    candidate = (left, right)

            if k <= 18:
                for mask in range(1 << k):
                    test(mask)
            else:
                seen = [0]
                chosen = []

                def search(pos, left_size):
                    if seen[0] >= 50000:
                        return
                    if pos == k:
                        seen[0] += 1
                        test(sum(1 << j for j in chosen))
                        return
                    search(pos + 1, left_size)
                    if left_size + sizes[union[pos]] < GPU_MEM_SIZE - eps:
                        chosen.append(pos)
                        search(pos + 1, left_size + sizes[union[pos]])
                        chosen.pop()

                search(0, 0.0)

            if candidate is not None:
                trial = [x[:] for x in bins]
                trial[worst] = candidate[0]
                trial[partner] = candidate[1]
                value = placement_pressure(trial)
                if value < best_value - 1e-12:
                    best_value = value
                    best_state = trial

        if best_state is None:
            break
        bins = best_state

    return {g: [models[i] for i in bins[g]] for g in range(gpu_num)}


